enum class Mode : unsigned short {
    None = 0, Read = 1 << 0, Write = 1 << 1, Append = 1 << 2
};

// Operator for combining flags (Mode | Mode -> Mode)
constexpr Mode operator|(Mode a, Mode b) {
    using T = unsigned short;
    return static_cast<Mode>(static_cast<T>(a) | static_cast<T>(b));
}

// Operator for checking flags (Mode & Mode -> bool)
constexpr bool operator&(Mode a, Mode b) {
    using T = unsigned short;
    return (static_cast<T>(a) & static_cast<T>(b)) != 0;
}

Mode current = Mode::Read | Mode::Append;

// Type-safe usage:
bool is_set = current & Mode::Append; // true
bool is_writing = current & Mode::Write; // false
